var e={kind:`board`,caption:`一棵 3 层的小 B+ 树（id 1～96，每个叶子页 8 行），按主键查 id = 63，再查 61～70`,stepTitles:{0:`从根页出发`,1:`页内找下一层`,2:`逐层往下`,3:`叶子页取数据`,4:`范围查询走链表`},cols:3,regions:[{id:`root`,label:`根页`},{id:`inner`,label:`第 2 层（非叶子页）`},{id:`leaf`,label:`叶子页（存整行）`}],legend:[[`hit`,`页内找到的那一条`],[`ok`,`走过的路径 / 命中的行`],[`bad`,`超出范围，停`]],frames:[{step:0,msg:`SELECT * FROM t WHERE id = 63`,boxes:{root:{items:[{t:`键 1 → 页 4`,st:null},{t:`键 33 → 页 5`,st:null},{t:`键 65 → 页 6`,st:null}],hot:!0,tag:`页 3`},inner:{items:[{t:`第 2 层共 3 页（还没读到）`}],tag:`　`},leaf:{items:[{t:`叶子层共 12 页（还没读到）`}],tag:`　`}},calc:[[`树高`,`3 层：根页 → 第 2 层 → 叶子页`],[`根页`,`页 3，常驻缓冲池（Buffer Pool）`]],note:`按主键查 id = 63。为了画得下，这里一个叶子页只放 8 行、一个非叶子页只有 4 个分叉（真实的 16KB 页能有上千个分叉）。查找总是从根页开始，根页几乎一直在内存的缓冲池里。`},{step:1,msg:`根页 3：页内找 63`,boxes:{root:{items:[{t:`键 1 → 页 4`,st:null},{t:`键 33 → 页 5`,st:`hit`},{t:`键 65 → 页 6`,st:null}],hot:!0,tag:`页 3　槽0≤65`},inner:{items:[{t:``}],tag:`　`},leaf:{items:[{t:``}],tag:`　`}},calc:[[`① 在槽上二分`,`槽0（最大键 65）≥ 63`],[`② 组内顺序找`,`扫过 1、33、65 → 不大于 63 的最大键是 33`],[`往下走`,`页 5`]],note:`根页里每条是「键 + 子页号」，按键排好序。先在页目录的槽上二分（每个槽管一组记录、记着组里最大的键），定位到组；再在组里顺序找「不大于 63 的最大键」33，它指向页 5。`},{step:2,msg:`读页 5（第 2 层）`,boxes:{root:{items:[{t:`键 1 → 页 4`,st:null},{t:`键 33 → 页 5`,st:`ok`},{t:`键 65 → 页 6`,st:null}],hot:!1,tag:`页 3`},inner:{items:[{t:`键 33 → 页 11`,st:null},{t:`键 41 → 页 12`,st:null},{t:`键 49 → 页 13`,st:null},{t:`键 57 → 页 14`,st:null}],hot:!0,tag:`页 5`},leaf:{items:[{t:``}],tag:`　`}},calc:[[`往下一层`,`读入页 5（第 2 层的另外 2 页不用读）`],[`已读`,`2 个页`]],note:`往下走一层就读一个页。第 2 层有 3 个页，只读路径上的页 5，别的页完全不碰。`},{step:1,msg:`页 5：页内找 63`,boxes:{root:{items:[{t:`键 1 → 页 4`,st:null},{t:`键 33 → 页 5`,st:`ok`},{t:`键 65 → 页 6`,st:null}],hot:!1,tag:`页 3`},inner:{items:[{t:`键 33 → 页 11`,st:null},{t:`键 41 → 页 12`,st:null},{t:`键 49 → 页 13`,st:null},{t:`键 57 → 页 14`,st:`hit`}],hot:!0,tag:`页 5　槽0≤57`},leaf:{items:[{t:``}],tag:`　`}},calc:[[`① 在槽上二分`,`槽0（最大键 57）< 63`],[`② 组内顺序找`,`扫过 33、41、49、57 → 不大于 63 的最大键是 57`],[`往下走`,`页 14`]],note:`同样两步：二分槽、组内顺序找，键 57 指向叶子页 14。`},{step:3,msg:`读叶子页 14：找 id = 63`,boxes:{root:{items:[{t:`键 1 → 页 4`,st:null},{t:`键 33 → 页 5`,st:`ok`},{t:`键 65 → 页 6`,st:null}],hot:!1,tag:`页 3`},inner:{items:[{t:`键 33 → 页 11`,st:null},{t:`键 41 → 页 12`,st:null},{t:`键 49 → 页 13`,st:null},{t:`键 57 → 页 14`,st:`ok`}],hot:!1,tag:`页 5`},leaf:{items:[{t:`id = 57`,st:null},{t:`id = 58`,st:null},{t:`id = 59`,st:null},{t:`id = 60`,st:null},{t:`id = 61`,st:null},{t:`id = 62`,st:null},{t:`id = 63（整行数据）`,st:`ok`},{t:`id = 64`,st:null}],hot:!0,tag:`页 14　槽0≤60  槽1≤64`}},calc:[[`① 在槽上二分`,`槽0（最大键 60）< 63，槽1（最大键 64）≥ 63`],[`② 组内顺序找`,`扫过 61、62、63 → 找到 63`],[`一共读了`,`3 个页（根页和第 2 层通常都在缓存里）`]],note:`到了叶子页，同样先二分槽、再组内顺序找，定位到 id = 63。聚簇索引的叶子里就是整行数据，直接返回。如果走的是二级索引，叶子里只有索引列和主键，还要拿主键回聚簇索引从根再查一遍（回表）。`},{step:4,msg:`SELECT * FROM t WHERE id BETWEEN 61 AND 70`,boxes:{root:{items:[{t:`键 1 → 页 4`,st:null},{t:`键 33 → 页 5`,st:`ok`},{t:`键 65 → 页 6`,st:null}],hot:!1,tag:`页 3`},inner:{items:[{t:`键 33 → 页 11`,st:null},{t:`键 41 → 页 12`,st:null},{t:`键 49 → 页 13`,st:null},{t:`键 57 → 页 14`,st:`ok`}],hot:!1,tag:`页 5`},leaf:{items:[{t:`id = 57`,st:null},{t:`id = 58`,st:null},{t:`id = 59`,st:null},{t:`id = 60`,st:null},{t:`id = 61`,st:`ok`},{t:`id = 62`,st:`ok`},{t:`id = 63（整行数据）`,st:`ok`},{t:`id = 64`,st:`ok`}],hot:!0,tag:`页 14　next → 页 15`}},calc:[[`先定位起点`,`和上面一样走到页 14 的 61`],[`往后顺序读`,`61、62、63、64`],[`读到页尾`,`顺着 next 指针去页 15`]],note:`范围查询：先按刚才的步骤找到起点 61，然后在叶子页里往后顺序读。读完这一页，顺着叶子页之间的链表指针去下一页 —— 不用回到根节点重新查。`},{step:4,msg:`沿链表读页 15，直到超过 70`,boxes:{root:{items:[{t:`键 1 → 页 4`,st:null},{t:`键 33 → 页 5`,st:null},{t:`键 65 → 页 6`,st:null}],hot:!1,tag:`页 3`},inner:{items:[{t:`键 33 → 页 11`,st:null},{t:`键 41 → 页 12`,st:null},{t:`键 49 → 页 13`,st:null},{t:`键 57 → 页 14`,st:null}],hot:!1,tag:`页 5`},leaf:{items:[{t:`id = 65`,st:`ok`},{t:`id = 66`,st:`ok`},{t:`id = 67`,st:`ok`},{t:`id = 68`,st:`ok`},{t:`id = 69`,st:`ok`},{t:`id = 70`,st:`ok`},{t:`id = 71`,st:`bad`},{t:`id = 72`,st:null}],hot:!0,tag:`页 15　prev ← 页 14`}},calc:[[`页 15`,`65、66、67、68、69、70`],[`遇到`,`71 > 70 → 停`],[`结果`,`10 行：61～70，只多读了 1 个叶子页`]],note:`在页 15 里接着读，读到 71 超过 70 就停。范围查询和 ORDER BY 主键都能这样顺着链表读，所以 B+ 树特别适合数据库。演示结束。`}]};export{e as default};